/**
 * Client Page Component: Structured Object Generation UI
 * Route: /ui/structured-data
 * 
 * Concepts Demonstrated:
 * 1. `experimental_useObject` Hook (@ai-sdk/react):
 *    - Purpose-built React hook for consuming structured JSON data generated by AI.
 *    - By supplying `schema: recipeSchema`, TypeScript automatically types `object` as `DeepPartial<RecipeOutput>`.
 * 2. Partial Object Hydration:
 *    - During streaming, `object` is progressively hydrated as fields are decoded.
 *    - Because properties can be partially defined while streaming, optional chaining
 *      (e.g., `object?.recipe?.ingredients?.map(...)`) is essential to prevent null-pointer crashes.
 * 3. Custom Request Payloads (`submit`):
 *    - Instead of being restricted to `{ prompt }`, `submit({ dish: dishName })`
 *      sends any arbitrary JSON payload to the target API endpoint.
 */

"use client";

import { useState } from "react";
import { experimental_useObject as useObject } from "@ai-sdk/react";
import { recipeSchema } from "../../api/structured-data/schema";

export default function StructuredDataPage() {
  // Local state for the dish name entered by the user
  const [dishName, setDishName] = useState("");

  // Initialize useObject with the target endpoint and validation schema
  const {
    submit,    // Function to trigger generation with custom parameters
    object,    // The typed structured object returned or streamed from the server
    isLoading, // True while generation/streaming is active
    error,     // Captured error object if generation fails
    stop,      // Abort controller function
  } = useObject({
    api: "/api/structured-data",
    schema: recipeSchema,
  });

  /**
   * Dispatches the dish name payload to the structured data API.
   */
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!dishName.trim() || isLoading) return;

    submit({ dish: dishName.trim() });
    setDishName("");
  };

  console.log("Current recipe object:", object);

  return (
    <div className="flex flex-col w-full max-w-md py-24 mx-auto stretch">
      <h1 className="text-xl font-bold mb-1">📊 Structured Data Generation</h1>
      <p className="text-sm text-gray-500 mb-6">
        Try asking for a recipe, e.g. &quot;Spaghetti Carbonara&quot; or &quot;Vegetable Biryani&quot;
      </p>

      {/* Error Banner */}
      {error && <div className="text-red-500 mb-4 px-4">{error.message}</div>}

      {/* Structured Recipe Output Presentation */}
      {object?.recipe && (
        <div className="space-y-6 px-4">
          {/* Recipe Title */}
          <h2 className="text-2xl font-bold text-white">{object.recipe.name}</h2>

          {/* Ingredients Grid */}
          {object?.recipe?.ingredients && (
            <div>
              <h3 className="text-xl font-semibold mb-4 text-zinc-200">Ingredients</h3>
              <div className="grid grid-cols-2 gap-4">
                {object.recipe.ingredients.map((ingredient, index) => (
                  <div
                    key={index}
                    className="bg-zinc-50 dark:bg-zinc-800 p-4 rounded-lg border border-zinc-700"
                  >
                    <p className="font-medium text-zinc-100">{ingredient?.name}</p>
                    <p className="text-zinc-600 dark:text-zinc-400 text-sm">
                      {ingredient?.amount}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Sequential Preparation Steps */}
          {object?.recipe?.steps && (
            <div>
              <h3 className="text-xl font-semibold mb-4 text-zinc-200">Steps</h3>
              <ol className="space-y-4">
                {object.recipe.steps.map((step, index) => (
                  <li
                    key={index}
                    className="bg-zinc-50 dark:bg-zinc-800 p-4 rounded-lg border border-zinc-700 text-zinc-200"
                  >
                    <span className="font-semibold text-blue-400 mr-2">{index + 1}.</span>
                    {step}
                  </li>
                ))}
              </ol>
            </div>
          )}
        </div>
      )}

      {/* Floating Prompt Bar */}
      <form
        onSubmit={handleSubmit}
        className="fixed bottom-0 w-full max-w-2xl mx-auto left-0 right-0 p-4 bg-zinc-50 dark:bg-zinc-950 border-t border-zinc-200 dark:border-zinc-800 shadow-lg"
      >
        <div className="flex gap-2">
          <input
            type="text"
            value={dishName}
            onChange={(e) => setDishName(e.target.value)}
            placeholder="Enter a dish name..."
            className="flex-1 dark:bg-zinc-800 p-2 border border-zinc-300 dark:border-zinc-700 rounded shadow-xl"
          />
          {isLoading ? (
            <button
              type="button"
              onClick={stop}
              className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Stop
            </button>
          ) : (
            <button
              type="submit"
              disabled={isLoading || !dishName.trim()}
              className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Generate
            </button>
          )}
        </div>
      </form>
    </div>
  );
}
